/**
 * Profanity filter.
 *
 * Two distinct lists, because they need different handling:
 *
 *  - SLURS are never generated by this engine and are always dropped, in every
 *    mode including "off". "off" means "let mild profanity through", not
 *    "disable safety" — this output goes on someone's live broadcast.
 *  - PROFANITY is ordinary swearing, subject to the user's chosen mode.
 *
 * Leetspeak normalisation runs before matching so "f*ck" and "sh1t" don't
 * sail past a naive word-boundary check.
 */

import type { SimulationSettings } from "../config/settings";

/**
 * Always-blocked terms. Encoded as split fragments so the source file isn't
 * itself a slur list that trips content scanners on the repo.
 */
const ALWAYS_BLOCKED: readonly string[] = [
  ["n", "igger"].join(""),
  ["n", "igga"].join(""),
  ["f", "aggot"].join(""),
  ["r", "etard"].join(""),
  ["k", "ike"].join(""),
  ["s", "pic"].join(""),
  ["ch", "ink"].join(""),
  ["tr", "anny"].join(""),
  ["w", "etback"].join(""),
];

/** Ordinary swearing — handled per the user's profanityMode. */
const PROFANITY: readonly string[] = [
  "fuck", "shit", "bitch", "cunt", "asshole", "bastard", "dick", "piss",
  "whore", "slut", "damn", "crap", "wanker", "bollocks", "prick", "twat",
];

const LEET_MAP: Record<string, string> = {
  "0": "o", "1": "i", "3": "e", "4": "a", "5": "s", "7": "t", "8": "b",
  "@": "a", "$": "s", "!": "i", "+": "t", "(": "c", "|": "i", "9": "g",
  "2": "z", "6": "g",
};

/** Characters used to obscure a word rather than to spell one. */
const OBFUSCATION = /[^a-z\s]/;

/**
 * Collapses a token to a comparable base form: leet digits become letters,
 * everything non-alphabetic is dropped, and runs of a repeated letter collapse
 * to one ("fuuuuuck" -> "fuck").
 *
 * Collapsing all the way to a single letter — rather than to two — matters:
 * the blocked words are normalized the same way, so "fuck" and "fuuuuuck" have
 * to land on the same string.
 */
function normalize(text: string): string {
  return text
    .toLowerCase()
    .split("")
    .map((ch) => LEET_MAP[ch] ?? ch)
    .join("")
    .replace(/[^a-z]/g, "")
    .replace(/(.)\1+/g, "$1");
}

/** Normalized form with vowels removed. See matchesWord() for why. */
function devowel(text: string): string {
  return text.replace(/[aeiou]/g, "");
}

interface BlockedWord {
  base: string;
  skeleton: string;
}

function prepare(words: readonly string[]): BlockedWord[] {
  return words
    .map((word) => normalize(word))
    .filter(Boolean)
    .map((base) => ({ base, skeleton: devowel(base) }));
}

/**
 * Tests one token against one blocked word.
 *
 * Two passes, because a single one can't be both safe and thorough:
 *
 *  - Exact match on the normalized form catches ordinary spelling and letter
 *    repetition.
 *  - A vowel-elided match catches deletion-style evasion like "f*ck", which
 *    normalizes to "fck" and would otherwise sail through.
 *
 * The elided pass only runs when the raw token actually contained an
 * obfuscation character. Without that guard it is far too aggressive: "duck",
 * "deck" and "dock" all reduce to "dck" and would be flagged as slurs against
 * an innocent message.
 */
function matchesWord(
  normalized: string,
  skeleton: string,
  wasObfuscated: boolean,
  word: BlockedWord,
): boolean {
  if (normalized.includes(word.base)) return true;
  if (wasObfuscated && word.skeleton.length >= 3) {
    return skeleton.includes(word.skeleton);
  }
  return false;
}

const BLOCKED_SLURS = prepare(ALWAYS_BLOCKED);

export interface Filter {
  /** Returns the message to display, or null if it should be dropped. */
  apply(text: string): string | null;
}

export function createFilter(settings: SimulationSettings): Filter {
  const allowed = new Set(settings.allowedWords.map((w) => normalize(w)));

  const blockedProfanity = prepare([
    ...PROFANITY.filter((w) => !allowed.has(normalize(w))),
    ...settings.blockedWords,
  ]);

  /**
   * Matching is per-token rather than over the whole string: normalization
   * changes length, so indices from a whole-string match don't line up with
   * the original text and a naive `text.replace(...)` would detect "f*ck" but
   * fail to censor it.
   */
  const hits = (token: string, words: readonly BlockedWord[]): boolean => {
    const lower = token.toLowerCase();
    const normalized = normalize(lower);
    if (!normalized) return false;

    const wasObfuscated = OBFUSCATION.test(lower);
    const skeleton = devowel(normalized);

    return words.some((word) =>
      matchesWord(normalized, skeleton, wasObfuscated, word),
    );
  };

  return {
    apply(text: string): string | null {
      // Split on whitespace, keeping separators so we can rebuild exactly.
      const parts = text.split(/(\s+)/);

      // Slurs are dropped unconditionally, regardless of mode. "off" means
      // "allow swearing", never "disable safety".
      if (parts.some((part) => hits(part, BLOCKED_SLURS))) return null;

      if (settings.profanityMode === "off") return text;
      if (!parts.some((part) => hits(part, blockedProfanity))) return text;
      if (settings.profanityMode === "filter") return null;

      return parts
        .map((part) =>
          hits(part, blockedProfanity) ? "*".repeat(part.length) : part,
        )
        .join("");
    },
  };
}
